// Auto-render: populate all .luna-icon[data-icon] elements with their SVG content.
// Runs on DOMContentLoaded and exposes renderLunaIcons() for dynamic content.
(function() {
    function renderLunaIcons(root) {
        (root || document).querySelectorAll('.luna-icon[data-icon]').forEach(function(el) {
            var name = el.getAttribute('data-icon');
            if (LUNA_ICONS[name] && !el.querySelector('svg')) {
                el.innerHTML = LUNA_ICONS[name];
            }
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() { renderLunaIcons(); });
    } else {
        renderLunaIcons();
    }
    window.renderLunaIcons = renderLunaIcons;
})();
